changeSet.sql:
REVOKE ALL ON FUNCTION fn_community_player_ids(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION
    fn_feed_for_player(uuid, int, int, text[], timestamptz, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION fn_community_player_ids(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION
    fn_feed_for_player(uuid, int, int, text[], timestamptz, text)
    TO anon, authenticated;

rollback.sql:
GRANT EXECUTE ON FUNCTION fn_community_player_ids(uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION
    fn_feed_for_player(uuid, int, int, text[], timestamptz, text) TO PUBLIC;
